const extra=B.flatMap((t,i)=>[.28,.56,.8].map((q,j)=>({t:t+(end(i)-t)*q,s:['tick_01','click_02','whoosh_04'][(i+j)%3]}))).filter(v=>base.every(b=>Math.abs(b.t-v.t)>.27));
export const SFX=[...base,...extra].sort((a,b)=>a.t-b.t).filter((v,i,a)=>i===0||v.t-a[i-1].t>=.25);
